<template><div class="app-container ps-page"><h2>知识冲突处置</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><el-form inline><el-form-item label="处置状态"><el-select v-model="query.state" clearable><el-option label="待处置" value="PENDING"/><el-option label="已处置" value="RESOLVED"/></el-select></el-form-item><el-button @click="load(true)">查询</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column prop="oldTitle" label="原文档" min-width="180"/><el-table-column prop="newTitle" label="新文档" min-width="180"/><el-table-column prop="reason" label="冲突原因" min-width="260" show-overflow-tooltip/><el-table-column prop="similarity" label="相似度" width="110"/><el-table-column label="状态" width="110"><template #default="{row}">{{stateLabel(row.state)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-hasPermi="['paismart:conflict:resolve']" link type="primary" @click="compare(row)">比较与处置</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load()"/><el-dialog v-model="open" title="冲突比较与业务影响" width="min(1100px,95vw)"><template v-if="selected"><el-row :gutter="16"><el-col :span="12"><h3>原文档 · {{selected.oldTitle||selected.oldDocumentId}}</h3><pre class="ps-pre compare-text">{{selected.oldText||'未返回冲突原文，请核对文档后处置'}}</pre></el-col><el-col :span="12"><h3>新文档 · {{selected.newTitle||selected.newDocumentId}}</h3><pre class="ps-pre compare-text">{{selected.newText||'未返回冲突原文，请核对文档后处置'}}</pre></el-col></el-row><el-alert title="保留新文档会删除整篇原文档；保留原文档会删除整篇新文档。忽略冲突只改变冲突状态。" type="warning" :closable="false" class="ps-section"/><el-form label-width="100px"><el-form-item label="处置方式"><el-select v-model="action"><el-option label="保留新文档，删除原文档" value="KEEP_NEW"/><el-option label="保留原文档，删除新文档" value="KEEP_EXISTING"/><el-option label="忽略冲突，保留两篇文档" value="IGNORED"/></el-select></el-form-item><el-form-item label="处置说明" required><el-input v-model="note" type="textarea" maxlength="500"/></el-form-item><el-form-item><el-checkbox v-model="confirmed">已核对整篇文档影响与保留版本</el-checkbox></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/></template><template #footer><el-button @click="open=false">关闭</el-button><el-button type="primary" :disabled="!confirmed||selected?.state==='RESOLVED'" :loading="saving" @click="resolve">确认处置</el-button></template></el-dialog><JobDialog v-model="jobOpen" :initial="job" @done="load()"/></div></template>
<script setup lang="ts">
import { onMounted,ref,shallowRef } from 'vue'
import { listConflicts,resolveConflict } from '@/api/paismart/governance'
import type { Conflict,Job } from '@/types/paismart'
import JobDialog from '../../components/JobDialog.vue'
import { errorText,stateLabel,usePage } from '../../composables/usePage'
import '../../common.css'
const {rows,total,query,loading,error,load}=usePage(listConflicts),selected=shallowRef<Conflict>(),job=shallowRef<Job>(),pageError=ref(''),formError=ref(''),open=ref(false),jobOpen=ref(false),saving=ref(false),action=ref('IGNORED'),note=ref(''),confirmed=ref(false)
function compare(row:Conflict){selected.value=row;action.value='IGNORED';note.value='';confirmed.value=false;formError.value='';open.value=true}
async function resolve(){if(!selected.value||!confirmed.value)return;if(!note.value.trim()){formError.value='请填写处置说明';return}saving.value=true;try{job.value=(await resolveConflict(selected.value,action.value,note.value)).data;open.value=false;if(job.value?.jobId)jobOpen.value=true;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
onMounted(()=>void load())
</script>
<style scoped>.compare-text{max-height:340px;overflow:auto;border:1px solid var(--el-border-color);padding:12px}</style>
